import hashlib

def deterministic_hash(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16) % (2 ** 32)

def build_ring(nodes, num_virtual=3):
    ring = {}
    for node in nodes:
        for v in range(num_virtual):
            point = deterministic_hash(f'{node}-{v}')
            ring[point] = node
    return ring

